SELECT @zoneCount = COUNT(*)
FROM OPENJSON(@json);

-- 4) Iterate each zone
DECLARE @i INT = 0;
WHILE @i < @zoneCount
BEGIN
    -- 4a) Count how many service-area entries this zone has
    DECLARE @saCount INT;
    SELECT @saCount = COUNT(*)
    FROM OPENJSON(@json, '$[' + CAST(@i AS VARCHAR(10)) + '].ZoneServiceArea');

