            @json,
            '$[' + CAST(@i AS VARCHAR(10)) + '].ZoneServiceArea[' 
                 + CAST(@j AS VARCHAR(10)) + '].Enabled',
            'false'
        );

        SET @j = @j + 1;
    END

    SET @i = @i + 1;
END

-- 5) Persist the updated JSON back to the table
